from pathlib import Path
R=Path(__file__).resolve().parent
src=(R/'finalize_common_contact.py').read_text(encoding='utf-8')
archive=R/'finalize_common_contact_displaced_not_adopted.py';assert not archive.exists()
archive.write_text("# Archived displaced-origin candidate; retained for provenance only.\nraise RuntimeError('Displaced-origin candidate was superseded by the centered layout. No promotion is allowed.')\n"+src,encoding='utf-8')
new=src.replace('audit/common_contact_summary.json','audit/common_contact_centered_summary.json').replace('native_common_contact_validation_','native_common_contact_centered_validation_').replace('COMMON_CONTACT_CANDIDATE_PROFILE.json','CENTERED_COMMON_CONTACT_CANDIDATE_PROFILE.json').replace('run_native_common_contact_fast_recorded.py','run_native_common_contact_centered.py').replace('audit/common_contact_motion_comparison.json','audit/common_contact_centered_motion_comparison.json')
new=new.replace("if not a.finalize:","motion_gate=json.loads((R/'audit/common_contact_centered_motion_gates.json').read_text())\nif not a.finalize:")
new=new.replace("promotion_performed=False)","motion_status=motion_gate['status'],motion_missing=len(motion_gate['missing']),promotion_performed=False)")
new=new.replace("checks=[];compression=[]", "assert motion_gate['status']=='PASSED' and len(motion_gate['rows'])==72 and not motion_gate['missing'] and not motion_gate['failed']\nfor proof in ['common_contact_centered_short_equivalence.json','common_contact_centered_gpu_short_equivalence.json']:assert json.loads((R/'audit'/proof).read_text())['passed']\nchecks=[];compression=[]")
new=new.replace("assert b['passed'] and done['complete']", "layout=json.loads((f/'coordinate_layout.json').read_text());assert layout['global_origins_m']==[[0.,0.,0.]]*9 and not layout['periodic_rebase'] and layout['native_collisions_disabled'];assert all(p[0]==0 and p[1]==0 for p in meta['initial_root_pose'])\n        assert b['passed'] and done['complete']")
new=new.replace("profile['known_limits']=", "profile['additional_motion_gate_maxima']={key:max(r[key] for r in motion_gate['rows']) for key in motion_gate['criteria']}\nprofile['known_limits']=")
new=new.replace('Forward displacement gates do not establish arbitrary world-origin invariance. Origin-dependent lateral drift is measured separately; reducing the step can worsen positional quantization at large global offsets.','The accepted layout centers independent environments near the origin and passes additional XY and heading gates. Moving them to large world offsets or much longer travel distances is outside this validation; displaced-origin failures remain recorded.')
new=new.replace("required=['COMMON_CONTRACT.json'", "required=['NUMERICAL_AMENDMENT_28.md','audit/common_contact_centered_summary.json','audit/common_contact_centered_motion_gates.json','audit/common_contact_centered_short_equivalence.json','audit/common_contact_centered_gpu_short_equivalence.json','audit/common_contact_centered_preparation.json','COMMON_CONTRACT.json'")
(R/'finalize_centered_common_contact.py').write_text(new,encoding='utf-8')
(R/'finalize_common_contact.py').write_text("\"\"\"Current finalizer: the centered layout supersedes the displaced-origin candidate.\"\"\"\nimport runpy\nfrom pathlib import Path\nrunpy.run_path(str(Path(__file__).resolve().parent/'finalize_centered_common_contact.py'),run_name='__main__')\n",encoding='utf-8')
